import React from "react";
import SinglePost from "./singelPostComponent";

class Home extends React.Component {

    constructor(props){
        super(props);

        this.state = {
            dataStat: [],
            data: [],
            loading: true
        };
    }

    componentDidMount() {
        fetch("http://localhost:8000/api/")
            .then(res => res.json())
            .then(data => {
                this.setState({
                    data: data,
                    loading: false
                });
            })
            .catch(err => console.log(err));
    }

    render() {

        if(this.state.loading){
            return <p>Loading...</p>;
        }

        return (
            <main className="container mt-4 pt-5">
                <div className="container-fluid mt-5">

                    {this.state.data.map((post)=>(
                        <SinglePost
                            key={post.id}
                            title={post.title}
                            text={post.text}
                            img={post.img}
                            user_img={post.user_img}
                            name={post.name}
                        />
                    ))}

                </div>
            </main>
        );
    }
}

export default Home;
